  function equationHasSources(input,q){const allowed=new Set(['0']),notations=new Set(derivedNumbers());for(const expression of [q.left,q.right,...route.table.rows.flatMap((r,ri)=>r.cells.flatMap((c,ci)=>c.expr?[c.expr,displayCell(c,ri,ci).expr]:[]))]){const m=E.inspect(expression);(m.numericLiterals||[]).forEach(x=>allowed.add(x));(m.numericNotations||[]).forEach(x=>notations.add(x));if(m.percent)allowed.add('100');}return E.hasNumberSources(input,[...allowed],[...notations]);}
  function newRun(p,r){const id='wp-'+Date.now()+'-'+Math.random().toString(36).slice(2,9);return {schema:1,interactionVersion:4,contentRevision:p.contentRevision||0,runId:id,scratchId:id,problemId:p.id,routeId:r.id,sourceLocation:'',modelGroupId:id,modelId:id,modelMethods:[],step:0,values:{},passed:{},attempts:{},firstPass:{},hints:{},seen:[],closure:[],conditionFound:[],conditionUsed:[],derivationSources:{},derived:{},verdict:'',reflection:'',customModel:'',discussion:'',assisted:false,example:false,finished:false,answersChecked:false,startedAt:new Date().toISOString()};}

