  function tableOptions(cell,ri,ci){const alternatives=[...(cell.alternatives||[]),...(T?.options(problem,route,ri,ci)||[])],ds=new Map((route.derivations||[]).map(d=>[d.id,derivationMethod(d)]));function requirements(ids){const refs=new Set();function visit(id){const d=ds.get(id);if(!d||refs.has(id))return;refs.add(id);for(const ref of d.sources||[])visit(ref);}for(const id of ids||[])visit(id);return [...refs].map(id=>({id,label:ds.get(id).label,completed:run.derived[id]===true}));}return {...cell,alternatives:alternatives.map(a=>({...a,requiredDerivations:requirements(a.sources)})),allowedNumbers:derivedNumbers(),sourceExpressions:(route.derivations||[]).filter(d=>run.derived[d.id]).flatMap(d=>[derivedExpression(d),d.result]),requiredDerivations:requirements(cell.sources)};}
