  function resetConfirmation(){return '<div id="wp-reset-confirm" class="wp-reset-confirm" data-wp-reset-confirm hidden role="group" aria-label="确认重置本题"><strong>重置本题分析？</strong><p id="wp-reset-description">本次填写、勾选、步骤进度和草稿纸将重新开始，返回本题第一步.已提交的历史记录会保留.</p><div><button type="button" class="wp-secondary" data-wp-cancel-reset>取消</button><button type="button" class="wp-primary" data-wp-confirm-reset aria-describedby="wp-reset-description">确认重置</button></div></div>';}
